@[inline] def i8 (bs : ByteArray) (i : Nat) : Int :=
  let v := u8 bs i
  if v ≥ 128 then (v : Int) - 256 else (v : Int)

@[inline] def i16 (bs : ByteArray) (i : Nat) : Int :=
  let v := u16 bs i
  if v ≥ 32768 then (v : Int) - 65536 else (v : Int)

def scanTables (bs : ByteArray) (numTables size : Nat) : Tables := Id.run do
  let mut t : Tables := {}
  for i in [0:numTables] do
    let dirOff := 12 + 16 * i
    if dirOff + 16 ≤ bs.size then
      let tag := u32 bs dirOff
      let off := u32 bs (dirOff + 8)
      let len := u32 bs (dirOff + 12)
      if off ≤ size then
        let clen := Nat.min len (size - off)
        if tag == tagHead then t := { t with head := some (off, clen) }
        else if tag == tagMaxp then t := { t with maxp := some (off, clen) }
        else if tag == tagCmap then t := { t with cmap := some (off, clen) }
        else if tag == tagLoca then t := { t with loca := some (off, clen) }
        else if tag == tagGlyf then t := { t with glyf := some (off, clen) }
        else if tag == tagHhea then t := { t with hhea := some (off, clen) }
        else if tag == tagHmtx then t := { t with hmtx := some (off, clen) }
        else if tag == tagKern then t := { t with kernT := some (off, clen) }
        else if tag == tagGPOS then t := { t with gpos := some (off, clen) }
        else if tag == tagPost then t := { t with post := some (off, clen) }
        else if tag == tagOS2 then t := { t with os2 := some (off, clen) }
  return t

def resolveCmap (bs : ByteArray) (cOff cLen : Nat) : Nat × Nat := Id.run do
  if cLen < 4 then return (0, 0)
  let numTables := u16 bs (cOff + 2)
  let mut bestScore := 0
  let mut bestOff := 0
  for i in [0:numTables] do
    let recOff := cOff + 4 + 8 * i
    let platform := u16 bs recOff
    let encoding := u16 bs (recOff + 2)
    let subOff := cOff + u32 bs (recOff + 4)
    let score := cmapScore platform encoding
    if score > bestScore && subOff < bs.size then
      let fmt := u16 bs subOff
      if fmt == 4 || fmt == 12 then
        bestScore := score
        bestOff := subOff
  if bestScore == 0 then return (0, 0)
  return (bestOff, u16 bs bestOff)

@[inline] def format4Glyph (bs : ByteArray) (idDeltaOff idRangeOff i sc codepoint : Nat) : Nat :=
  let delta := i16 bs (idDeltaOff + 2 * i)
  let iro := u16 bs (idRangeOff + 2 * i)
  if iro == 0 then (Int.emod ((codepoint : Int) + delta) 65536).toNat
  else
    let g := u16 bs (idRangeOff + 2 * i + iro + 2 * (codepoint - sc))
    if g == 0 then 0 else (Int.emod ((g : Int) + delta) 65536).toNat

def isCmapSorted (bs : ByteArray) (so fmt : Nat) : Bool := Id.run do
  let (n, startOff, endOff, stride) :=
    if fmt == 4 then
      let segCount := u16 bs (so + 6) / 2
      (segCount, so + 14 + segCount * 2 + 2, so + 14, 2)
    else if fmt == 12 then (format12Cap bs so, so + 16, so + 20, 12)
    else (0, 0, 0, 0)
  let get := fun (off : Nat) => if fmt == 4 then u16 bs off else u32 bs off
  let mut prevEnd : Int := -1
  for i in [0:n] do
    let sc := get (startOff + stride * i)
    let ec := get (endOff + stride * i)
    if (sc : Int) ≤ prevEnd || ec < sc then return false
    prevEnd := ec
  return true

def glyphIdFormat12 (bs : ByteArray) (so : Nat) (codepoint : Nat) : Nat := Id.run do
  let groupsOff := so + 16
  for i in [0:format12Cap bs so] do
    let go := groupsOff + 12 * i
    let startChar := u32 bs go
    let endChar := u32 bs (go + 4)
    let startGlyph := u32 bs (go + 8)
    if startChar ≤ codepoint && codepoint ≤ endChar then
      return startGlyph + (codepoint - startChar)
  return 0

def resolveKern (bs : ByteArray) (kOff kLen : Nat) : Nat × Nat := Id.run do
  if kLen < 4 then return (0, 0)
  let nTables := u16 bs (kOff + 2)
  let mut off := kOff + 4
  for _ in [0:nTables] do
    let subLength := u16 bs (off + 2)
    let coverage := u16 bs (off + 4)
    let format := coverage / 256
    let horizontal := coverage &&& 0x1 != 0
    if format == 0 && horizontal then
      let nPairs := u16 bs (off + 6)
      return (off + 14, nPairs)
    off := off + (if subLength == 0 then 6 else subLength)
  return (0, 0)

def classOf (bs : ByteArray) (off gid : Nat) : Nat := Id.run do
  if off == 0 then return 0
  let fmt := u16 bs off
  if fmt == 1 then
    let startG := u16 bs (off + 2)
    let glyphCount := u16 bs (off + 4)
    if gid ≥ startG && gid - startG < glyphCount then
      return u16 bs (off + 6 + 2 * (gid - startG))
    return 0
  else if fmt == 2 then
    let rangeCount := u16 bs (off + 2)
    for i in [0:rangeCount] do
      let ro := off + 4 + 6 * i
      let startG := u16 bs ro
      let endG := u16 bs (ro + 2)
      if startG ≤ gid && gid ≤ endG then return u16 bs (ro + 4)
    return 0
  else return 0

def valueRecordSize (fmt : Nat) : Nat :=
  let b := fun m => if fmt &&& m != 0 then 1 else 0
  2 * (b 0x0001 + b 0x0002 + b 0x0004 + b 0x0008 + b 0x0010 + b 0x0020 + b 0x0040 + b 0x0080)

def pairPosFormat2 (bs : ByteArray) (so left right : Nat) : Option Int := Id.run do
  let coverageOff := so + u16 bs (so + 2)
  match coverageIndex bs coverageOff left with
  | none => return none
  | some _ =>
    let valueFormat1 := u16 bs (so + 4)
    let valueFormat2 := u16 bs (so + 6)
    let classDef1Off := so + u16 bs (so + 8)
    let classDef2Off := so + u16 bs (so + 10)
    let class1Count := u16 bs (so + 12)
    let class2Count := u16 bs (so + 14)
    let c1 := classOf bs classDef1Off left
    let c2 := classOf bs classDef2Off right
    if c1 ≥ class1Count || c2 ≥ class2Count then return none
    let recSize := valueRecordSize valueFormat1 + valueRecordSize valueFormat2
    let classRecOff := so + 16 + (c1 * class2Count + c2) * recSize
    match xAdvanceOffset valueFormat1 with
    | some xoff => return some (i16 bs (classRecOff + xoff))
    | none => return some 0

def advance (f : Font) (gid : Nat) : Nat :=
  if gid ≥ f.numGlyphs || f.numberOfHMetrics == 0 then 0
  else if gid < f.numberOfHMetrics then tu16 f (f.hmtxOff + 4 * gid)
  else tu16 f (f.hmtxOff + 4 * (f.numberOfHMetrics - 1))

def locaOffset (f : Font) (i : Nat) : Nat :=
  if f.indexToLocFormat == 1 then tu32 f (f.locaOff + 4 * i)
  else 2 * tu16 f (f.locaOff + 2 * i)

def glyphSpan (f : Font) (gid : Nat) : Option (Nat × Nat) :=
  if gid ≥ f.numGlyphs then none
  else
    let o0 := locaOffset f gid
    let o1 := locaOffset f (gid + 1)
    if o1 < o0 then none
    else
      let off := f.glyfOff + o0
      if off > f.extent then none
      else
        let tableEnd := Nat.min f.extent (f.glyfOff + f.glyfLen)
        let len := if off > tableEnd then 0 else Nat.min (o1 - o0) (tableEnd - off)
        some (off, len)

def glyphRecord (f : Font) (off len : Nat) : ByteArray × Nat :=
  if off < f.data.size || f.tailChunks.isEmpty then (f.data, off)
  else (base64Range f.tailChunks f.tailChunkBytes (off - f.data.size) len, 0)

def degToRad16 (deg : Fx) : Int :=
  let d := Int.emod deg (360 * 256)
  Int.ediv (d * 205887) 46080

def rotate (deg : Fx) : Mat :=
  let (s, c) := sinCos16 (degToRad16 deg)
  mk' c s (-s) c 0 0

def skewX (deg : Fx) : Mat :=
  let (s, c) := sinCos16 (degToRad16 deg)
  let t := if c == 0 then linMax else Int.ediv (s * 65536) c
  mk' 65536 0 t 65536 0 0

def skewY (deg : Fx) : Mat :=
  let (s, c) := sinCos16 (degToRad16 deg)
  let t := if c == 0 then linMax else Int.ediv (s * 65536) c
  mk' 65536 t 0 65536 0 0

def cubicDeltaFromLine (a b c d : Fx) : Fx :=
  let oneThird := Fx.abs (Int.ediv ((a * 8 - b * 15 + c * 6 + d) * 19) 512)
  let twoThird := Fx.abs (Int.ediv ((a + b * 6 - c * 15 + d * 8) * 19) 512)
  Fx.max oneThird twoThird

def diffToShift (dx dy : Fx) : Nat :=
  let dist := (Int.ediv (cheapDistance dx dy + 16) 32).toNat
  bitLength dist / 2

def strokeReach (st : StrokeStyle) : Fx :=
  let hw := Int.ediv st.width 2
  if hw ≤ 0 then 0
  else
    let ml := -(Int.ediv (-st.miterLimit) 256)
    Fx.clamp ((hw + 2) * (if ml < 2 then 2 else ml) + 2)

def arcSteps (r : Fx) : Nat :=
  let rpx := (Int.ediv r 256).toNat
  Nat.min 64 (Nat.max 8 (Nat.sqrt (rpx * 8) + 8))

def rotBy (v : Pt) (s co : Int) : Pt :=
  ⟨Fx.clamp (Int.ediv (v.x * co - v.y * s) 65536),
   Fx.clamp (Int.ediv (v.x * s + v.y * co) 65536)⟩

def DSeg.tangentAt (s : DSeg) (pos L : Fx) : Pt :=
  if (s.tp.x == 0 && s.tp.y == 0) || (s.tq.x == 0 && s.tq.y == 0) then ⟨0, 0⟩
  else ⟨s.tp.x * (L - pos) + s.tq.x * pos, s.tp.y * (L - pos) + s.tq.y * pos⟩

def scaleDecimal (mant : Nat) (exp10 : Int) (scale cap : Nat) : Nat :=
  if mant == 0 then 0
  else if exp10 > 60 then cap
  else if exp10 < -60 then 0
  else if exp10 ≥ 0 then Nat.min cap (mant * scale * 10 ^ exp10.toNat)
  else Nat.min cap ((mant * scale * 2 / 10 ^ (-exp10).toNat + 1) / 2)

open Bytes in

def parseNumber (bs : ByteArray) (i : Nat) : Option (Fx × Nat) :=
  match parseDecimal bs i with
  | none => none
  | some (neg, mant, exp10, j) =>
    let r : Fx := Fx.clamp (Int.ofNat (scaleDecimal mant exp10 256 Fx.maxVal.toNat))
    some (if neg then -r else r, j)

def parseLength (bs : ByteArray) (i : Nat) : Option (Fx × Nat) :=
  match parseNumber bs i with
  | none => none
  | some (v, j) =>
    if startsWith bs j "px" then some (v, j + 2)
    else if startsWith bs j "pt" then some (Int.ediv (v * 4) 3, j + 2)
    else if startsWith bs j "pc" then some (v * 16, j + 2)
    else if startsWith bs j "mm" then some (Int.ediv (v * 960) 254, j + 2)
    else if startsWith bs j "cm" then some (Int.ediv (v * 9600) 254, j + 2)
    else if startsWith bs j "in" then some (v * 96, j + 2)
    else if startsWith bs j "em" then some (v * 16, j + 2)
    else if startsWith bs j "ex" then some (v * 8, j + 2)
    else if at' bs j == 37 then none
    else some (v, j)

def parseLength16 (bs : ByteArray) (i : Nat) : Option (Int × Nat) :=
  match parseNumber16 bs i with
  | none => none
  | some (v, j) =>
    let v := if v > Fx.maxVal * 256 then Fx.maxVal * 256
             else if v < -(Fx.maxVal * 256) then -(Fx.maxVal * 256) else v
    if startsWith bs j "px" then some (v, j + 2)
    else if startsWith bs j "pt" then some (Int.ediv (v * 4) 3, j + 2)
    else if startsWith bs j "pc" then some (v * 16, j + 2)
    else if startsWith bs j "mm" then some (Int.ediv (v * 960) 254, j + 2)
    else if startsWith bs j "cm" then some (Int.ediv (v * 9600) 254, j + 2)
    else if startsWith bs j "in" then some (v * 96, j + 2)
    else if startsWith bs j "em" then some (v * 16, j + 2)
    else if startsWith bs j "ex" then some (v * 8, j + 2)
    else if at' bs j == 37 then none
    else some (v, j)

