def grammar : Array (Re × Nat) :=
  let s := fun (l : List Nat) => sym l
  let c := s [cC, cRa]
  let n := seq (opt (seq (opt (s [cZWNJ])) (s [cRS]))) (opt (seq (s [cN]) (opt (s [cN]))))
  let z := s [cZWJ, cZWNJ]
  let reph := alt (seq (s [cRa]) (s [cH])) (s [cRepha])
  let sm := s [cSM, cSMPst]
  let cn := seq c (seq (opt (s [cZWJ])) (opt n))
  let symbol := seq (s [cSymbol]) (opt (s [cN]))
  let matraGroup := seq (star z) (seq (alt (s [cM]) (seq (opt sm) (s [cMPst])))
    (seq (opt (s [cN])) (opt (s [cH]))))
  let syllableTail := seq (opt (seq (opt z) (seq sm (seq (opt sm) (opt (s [cZWNJ]))))))
    (star (s [cA]))
  let halantGroup := seq (opt z) (seq (s [cH]) (opt (seq (s [cZWJ]) (opt (s [cN])))))
  let finalHalantGroup := alt halantGroup (seq (s [cH]) (s [cZWNJ]))
  let medialGroup := opt (s [cCM])
  let halantOrMatraGroup := alt finalHalantGroup (star matraGroup)
  let complexTail := seq (star (seq halantGroup cn))
    (seq medialGroup (seq halantOrMatraGroup syllableTail))
  let consonantSyllable := seq (opt (s [cRepha, cCS])) (seq cn complexTail)
  let vowelSyllable := seq (opt reph) (seq (s [cV]) (seq (opt n) (alt (s [cZWJ]) complexTail)))
  let standalone := seq (alt (seq (opt (s [cRepha, cCS])) (s [cPlaceholder]))
    (seq (opt reph) (s [cDottedCircle]))) (seq (opt n) complexTail)
  let symbolCluster := seq symbol syllableTail
  let broken := seq (opt reph) (seq (opt n) complexTail)
  #[(consonantSyllable, 0), (vowelSyllable, 1), (standalone, 2), (symbolCluster, 3),
    (s [cSMPst], 5), (broken, 4)]

def moveGlyph (src dst : Nat) : M Unit := modify fun s => Id.run do
  let x := s.info.getD src default
  let mut info := s.info
  if src < dst then
    for k in [src:dst] do info := info.setIfInBounds k (info.getD (k + 1) default)
  else if dst < src then
    for k in [0:src - dst] do info := info.setIfInBounds (src - k) (info.getD (src - k - 1) default)
  info := info.setIfInBounds dst x
  return { s with info := info }

def Layout.ofBytes (bs : ByteArray) : Layout := Id.run do
  let mut l : Layout := { bs := bs }
  match findTable bs tagGSUB with
  | some (o, len) => if len ≥ 10 && u16 bs o == 1 then l := { l with gsub := o }
  | none => pure ()
  match findTable bs tagGPOS with
  | some (o, len) => if len ≥ 10 && u16 bs o == 1 then l := { l with gpos := o }
  | none => pure ()
  match findTable bs tagGDEF with
  | some (o, len) =>
    if len ≥ 12 && u16 bs o == 1 then
      let rel := fun (k : Nat) => let v := u16 bs (o + k); if v == 0 then 0 else o + v
      l := { l with classDef := rel 4, markAttach := rel 10 }
      if u16 bs (o + 2) ≥ 2 && len ≥ 14 then l := { l with markSets := rel 12 }
  | none => pure ()
  return l

def lookupCount (l : Layout) (gpos : Bool) : Nat :=
  let t := l.base gpos
  if t == 0 then 0 else u16 l.bs (t + u16 l.bs (t + 8))

def lookupOff (l : Layout) (gpos : Bool) (li : Nat) : Nat :=
  let t := l.base gpos
  let ll := t + u16 l.bs (t + 8)
  ll + u16 l.bs (ll + 2 + 2 * li)

def defaultLangSys (l : Layout) (script : Nat) : Option Nat :=
  let o := u16 l.bs script
  if o == 0 then none else some (script + o)

def featureListOff (l : Layout) (gpos : Bool) : Nat :=
  let t := l.base gpos
  t + u16 l.bs (t + 6)

def tag (s : String) : Nat :=
  let b := s.toUTF8
  u32 b 0

def nextGlyph : M Unit := modify fun s =>
  if s.haveOutput then
    if s.out.size ≥ s.maxLen then { s with ok := false }
    else { s with out := s.out.push (s.cur), idx := s.idx + 1 }
  else { s with idx := s.idx + 1 }

def bufReplace (g : Nat) : M Unit := modify fun s =>
  if s.out.size ≥ s.maxLen then { s with ok := false }
  else { s with out := s.out.push { s.cur with gid := g }, idx := s.idx + 1 }

def bufOutput (g : Nat) : M Unit := modify fun s =>
  if s.out.size ≥ s.maxLen then { s with ok := false }
  else if s.idx < s.len then { s with out := s.out.push { s.cur with gid := g } }
  else match s.out.back? with
    | some b => { s with out := s.out.push { b with gid := g } }
    | none => s

def checkProp (l : Layout) (g : GInfo) (props : Nat) : Bool :=
  if g.gprops &&& props &&& 0x0E != 0 then false
  else if g.isMark then
    if props &&& 0x10 != 0 then l.isMarkGlyph g.gid (props >>> 16)
    else if props &&& 0xFF00 != 0 then (props &&& 0xFF00) == (g.gprops &&& 0xFF00)
    else true
  else true

def replaceGlyphInplace (g : Nat) : M Unit := do
  setGlyphClass g 0 false false
  modify fun s => { s with info := s.info.setIfInBounds s.idx { s.cur with gid := g } }

def resolveExt (l : Layout) (gpos : Bool) (typ off : Nat) : Nat × Nat :=
  if (gpos && typ == 9) || (!gpos && typ == 7) then
    if u16 l.bs off == 1 then (u16 l.bs (off + 2), off + u32 l.bs (off + 4)) else (0, 0)
  else (typ, off)

def readRule (bs : ByteArray) (off : Nat) : Rule :=
  let gc := u16 bs off
  let rc := u16 bs (off + 2)
  let ni := if gc == 0 then 0 else gc - 1
  { input := readArr bs (off + 4) ni, records := readRecords bs (off + 4 + 2 * ni) rc }

def lookupProps (l : Layout) (lo : Nat) : Nat :=
  let flag := u16 l.bs (lo + 2)
  if flag &&& 0x10 != 0 then flag ||| (u16 l.bs (lo + 6 + 2 * u16 l.bs (lo + 4)) <<< 16) else flag

def scriptOf (cp : Nat) : String :=
  let i := lookupRuns scRuns cp
  String.Pos.Raw.extract scriptTags ⟨4 * i⟩ ⟨4 * i + 4⟩

def indicCatPos (cp : Nat) : Nat × Nat :=
  let v := lookupRuns indicRuns cp
  (v / 256, v % 256)

def boldWidth (size : Fx) (scale : Nat) : Fx :=
  let dev : Int := Int.ediv (size * scale) 65536
  let s := max 2304 (min 9216 dev)
  Int.ediv (size * (27648 - (s - 2304))) 663552

def matchStretch (avail : List Nat) (s : Nat) : Nat :=
  if avail.contains s then s
  else
    let narrower := avail.filter (· < s)
    let wider := avail.filter (· > s)
    let nearest := fun (l : List Nat) => l.foldl (fun b x =>
      if (if x < s then s - x else x - s) < (if b < s then s - b else b - s) then x else b) (l.headD s)
    if s ≤ 5 then (if narrower.isEmpty then nearest wider else nearest narrower)
    else (if wider.isEmpty then nearest narrower else nearest wider)

def pick (head weight : Nat) (italic : Bool) (matchWeight : List Nat → Nat → Nat)
    (stretch : Nat := 5) : Nat :=
  let fam := ((FontSet.entries[head]?).map (·.family)).getD ""
  let prevFam := if head == 0 then "" else ((FontSet.entries[head - 1]?).map (·.family)).getD ""
  if prevFam == fam then head
  else
    let all := (List.range FontSet.entries.size).filter (fun k =>
      ((FontSet.entries[k]?).map (·.family)).getD "" == fam)
    let styleOf := fun (k : Nat) => (FontSet.styles.getD k (400, false, 5))
    let st := matchStretch (all.map (fun k => (styleOf k).2.2)) stretch
    let faces := all.filter (fun k => (styleOf k).2.2 == st)
    let slanted := faces.filter (fun k => (styleOf k).2.1)
    let cands := if italic && !slanted.isEmpty then slanted else faces.filter (fun k => !(styleOf k).2.1)
    let w := matchWeight (cands.map (fun k => (styleOf k).1)) weight
    (cands.find? (fun k => (styleOf k).1 == w)).getD head

def fallbackOrder (base count : Nat) : List Nat :=
  if suite base then List.range count
  else dejaVuSans :: stixTwoMath :: List.range count

def Cub.ofQuad (a c b : Int × Int) : Cub :=
  ⟨a, (a.1 + rdiv (2 * (c.1 - a.1)) 3, a.2 + rdiv (2 * (c.2 - a.2)) 3),
      (b.1 + rdiv (2 * (c.1 - b.1)) 3, b.2 + rdiv (2 * (c.2 - b.2)) 3), b⟩

def pieceCount (c : Cub) : Nat :=
  let f := fun (p : Int × Int) => (⟨Int.ediv p.1 256, Int.ediv p.2 256⟩ : Pt)
  Nat.min 64 (4 * segCount Mat.identity (f c.p0) (f c.p1) (f c.p2) (f c.p3))

def Seg.arclenTo (s : Seg) (m : Nat) : Int :=
  let step := tOne / s.n
  let k := Nat.min (s.n - 1) (m / step)
  s.cum.getD k 0 + chord (s.pts.getD k (0, 0)) (s.c.eval m)

def unit (d : Int × Int) : Int × Int :=
  let l := Nat.sqrt (d.1.natAbs * d.1.natAbs + d.2.natAbs * d.2.natAbs)
  if l == 0 then (0, 65536)
  else
    let l : Int := l
    (rdiv (d.1 * 65536) l, rdiv (d.2 * 65536) l)

def accuracyFor (a b c d : Int) : Int :=
  let sx := Nat.sqrt (a.natAbs * a.natAbs + b.natAbs * b.natAbs)
  let sy := Nat.sqrt (c.natAbs * c.natAbs + d.natAbs * d.natAbs)
  let s : Int := Nat.sqrt (sx * sy)
  Int.ediv (32768 * 65536) (max 65536 s)

def read255 (bs : ByteArray) (off : Nat) : Nat × Nat :=
  let c := u8 bs off
  if c == 253 then (u16 bs (off + 1), off + 3)
  else if c == 255 then (u8 bs (off + 1) + 253, off + 2)
  else if c == 254 then (u8 bs (off + 1) + 506, off + 2)
  else (c, off + 1)

def triplet (bs : ByteArray) (flag off : Nat) : Int × Int × Nat :=
  let sgn := fun (f : Nat) (v : Nat) => if f % 2 == 1 then (v : Int) else -(v : Int)
  let b0 := u8 bs off
  let b1 := u8 bs (off + 1)
  let b2 := u8 bs (off + 2)
  let b3 := u8 bs (off + 3)
  if flag < 10 then (0, sgn flag (((flag &&& 14) <<< 7) + b0), 1)
  else if flag < 20 then (sgn flag ((((flag - 10) &&& 14) <<< 7) + b0), 0, 1)
  else if flag < 84 then
    let f := flag - 20
    (sgn flag (1 + (f &&& 0x30) + (b0 >>> 4)), sgn (flag >>> 1) (1 + ((f &&& 0x0C) <<< 2) + (b0 &&& 0x0F)), 1)
  else if flag < 120 then
    let f := flag - 84
    (sgn flag (1 + ((f / 12) <<< 8) + b0), sgn (flag >>> 1) (1 + (((f % 12) >>> 2) <<< 8) + b1), 2)
  else if flag < 124 then
    (sgn flag ((b0 <<< 4) + (b1 >>> 4)), sgn (flag >>> 1) (((b1 &&& 0x0F) <<< 8) + b2), 3)
  else (sgn flag ((b0 <<< 8) + b1), sgn (flag >>> 1) ((b2 <<< 8) + b3), 4)

def readVarLen8 (inp : ByteArray) (bp : Nat) : Nat × Nat :=
  if peek inp bp 1 == 0 then (0, bp + 1)
  else
    let n := peek inp (bp + 1) 3
    if n == 0 then (1, bp + 4)
    else ((1 <<< n) + peek inp (bp + 4) n, bp + 4 + n)

def Blocks.header (inp : ByteArray) (bp : Nat) : Option (Blocks × Nat) := do
  let (v, bp) := readVarLen8 inp bp
  let n := v + 1
  if n < 2 then return ({ n }, bp)
  let (types, bp) ← readCode inp bp (n + 2)
  let (counts, bp) ← readCode inp bp 26
  let (left, bp) ← readBlockLen inp counts bp
  return ({ n, types, counts, left }, bp)

def Blocks.step (b : Blocks) (inp : ByteArray) (bp : Nat) : Option (Blocks × Nat) := do
  if b.n < 2 then return (b, bp)
  if b.left > 0 then return ({ b with left := b.left - 1 }, bp)
  let (s, bp) ← b.types.read inp bp
  let t0 := if s == 0 then b.last2 else if s == 1 then b.cur + 1 else s - 2
  let t := if t0 ≥ b.n then t0 - b.n else t0
  let (left, bp) ← readBlockLen inp b.counts bp
  if left == 0 then none
  return ({ b with cur := t, last2 := b.cur, left := left - 1 }, bp)

def windowOf (inp : ByteArray) : Option (Nat × Nat) :=
  if peek inp 0 1 == 0 then some ((1 <<< 16) - 16, 1)
  else
    let n := peek inp 1 3
    if n != 0 then some ((1 <<< (17 + n)) - 16, 4)
    else
      let m := peek inp 4 3
      if m == 1 then none
      else if m != 0 then some ((1 <<< (8 + m)) - 16, 7)
      else some ((1 <<< 17) - 16, 7)

def readLens (inp : ByteArray) (cl : Huff) (total : Nat) :
    Nat → Nat → Array Nat → Option (Nat × Array Nat)
  | 0, bp, acc => if acc.size == total then some (bp, acc) else none
  | fuel + 1, bp, acc =>
    if acc.size ≥ total then (if acc.size == total then some (bp, acc) else none) else
    match sym inp cl bp with
    | none => none
    | some (s, bp) =>
      if s < 16 then readLens inp cl total fuel bp (acc.push s)
      else
        let (v, n, bp) :=
          if s == 16 then (acc.back?.getD 0, 3 + peek inp bp 2, bp + 2)
          else if s == 17 then (0, 3 + peek inp bp 3, bp + 3)
          else (0, 11 + peek inp bp 7, bp + 7)
        if (s == 16 && acc.size == 0) || acc.size + n > total || bp > 8 * inp.size then none
        else readLens inp cl total fuel bp (acc ++ Array.replicate n v)

def skipAtRule (src : ByteArray) (i0 limit : Nat) : Nat :=
  let stop := scanFor src i0 limit (fun c => c == 59 || c == 123)
  if stop ≥ limit then limit
  else if at' src stop == 59 then stop + 1
  else skipBlock src (stop + 1) limit

def splitImportant (raw : ByteArray) : (ByteArray × Bool) :=
  let t := trim raw
  match lastIndexOf t 33 with                  
  | none => (t, false)
  | some p =>
    let after := trim (t.extract (p + 1) t.size)
    if eqAscii after "important" then (trim (t.extract 0 p), true) else (t, false)

def matchingDeclsSplit (rules : Array Rule) (chain : Array ElemInfo) :
    (Array (String × ByteArray) × Array (String × ByteArray)) := Id.run do
  let mut normal : Array (String × ByteArray) := #[]
  let mut important : Array (String × ByteArray) := #[]
  for rule in rules do
    if «matches» rule.selector chain then
      for d in rule.decls do
        if d.important then important := important.push (d.name, d.value)
        else normal := normal.push (d.name, d.value)
  return (normal, important)

def resolve (rules : Array Rule) (chain : Array ElemInfo) : Array (String × ByteArray) :=
  let (normal, important) := matchingDeclsSplit rules chain
  normal ++ important

def buildElemInfo (tag : String) (attrs : Array (String × String)) (isFirstChild : Bool) : ElemInfo :=
  let id := (attrs.find? (fun a => a.1 == "id")).map (·.2) |>.getD ""
  let classes := match attrs.find? (fun a => a.1 == "class") with
    | some (_, v) => splitWs v
    | none => #[]
  { tag, id, classes, attrs, isFirstChild }

def posKeyword (w : ByteArray) : Option (Nat × LP) :=
  if eqAsciiCI w "left" then some (0, pct 0)
  else if eqAsciiCI w "right" then some (0, pct 100)
  else if eqAsciiCI w "top" then some (1, pct 0)
  else if eqAsciiCI w "bottom" then some (1, pct 100)
  else if eqAsciiCI w "center" then some (2, pct 50)
  else none

def circleOf (env : Env) (ws : Array ByteArray) : Option Geo :=
  match ws.findIdx? (eqAsciiCI · "at") with
  | some k =>
    if k > 1 then none
    else
      let r := if k == 0 then some .closest else radiusOf env (ws.getD 0 ByteArray.empty)
      match r, positionOf env (ws.extract (k + 1) ws.size) with
      | some r, some (x, y) => some (.circle r x y)
      | _, _ => none
  | none =>
    if ws.size == 0 then some (.circle .closest (pct 50) (pct 50))
    else if ws.size == 1 then (radiusOf env (ws.getD 0 ByteArray.empty)).map fun r => .circle r (pct 50) (pct 50)
    else none

def ellipseOf (env : Env) (ws : Array ByteArray) : Option Geo :=
  let k := (ws.findIdx? (eqAsciiCI · "at")).getD ws.size
  let pos := if k == ws.size then some (pct 50, pct 50) else positionOf env (ws.extract (k + 1) ws.size)
  let radii : Option (Radius × Radius) :=
    if k == 0 then some (.closest, .closest)
    else if k == 2 then
      match radiusOf env (ws.getD 0 ByteArray.empty), radiusOf env (ws.getD 1 ByteArray.empty) with
      | some a, some b => some (a, b)
      | _, _ => none
    else none
  match radii, pos with
  | some (a, b), some (x, y) => some (.ellipse a b x y)
  | _, _ => none

def fillRule (args : ByteArray) : Bool × ByteArray :=
  let c := findByte args 0 44
  let head := trim (args.extract 0 c)
  if eqAsciiCI head "evenodd" then (true, args.extract (c + 1) args.size)
  else if eqAsciiCI head "nonzero" then (false, args.extract (c + 1) args.size)
  else (false, args)

def pathOf (env : Env) (args : ByteArray) : Option Geo :=
  let (eo, rest) := fillRule args
  let s := trim rest
  let q := at' s 0
  if s.size < 2 || !(q == 34 || q == 39) || at' s (s.size - 1) != q then none
  else
    let cmds := env.pathData (s.extract 1 (s.size - 1))
    if cmds.size == 0 || cmds.size > maxPathCmds then none else some (.path eo cmds)

def parse (env : Env) (bs : ByteArray) : Option Spec :=
  let t := trim bs
  let o := findByte t 0 40
  if o ≥ t.size then
    (boxKeyword t).map fun b => ⟨.box, b⟩
  else
    let c := closeParen t o
    if c ≥ t.size then none
    else
      let pre := words (t.extract 0 o)
      let post := words (t.extract (c + 1) t.size)
      let name := lower (pre.back?.getD ByteArray.empty)
      let args := t.extract (o + 1) c
      let boxes := (pre.pop ++ post).map boxKeyword

      if o == 0 || isWs (at' t (o - 1)) || boxes.size > 1 || boxes.any Option.isNone then none
      else
        let ref := (boxes.getD 0 (some .stroke)).getD .stroke
        let geo :=
          if eqAscii name "circle" then circleOf env (words args)
          else if eqAscii name "ellipse" then ellipseOf env (words args)
          else if eqAscii name "inset" then insetOf env (words args)
          else if eqAscii name "rect" then rectOf env (words args)
          else if eqAscii name "xywh" then xywhOf env (words args)
          else if eqAscii name "polygon" then polygonOf env args
          else if eqAscii name "path" then pathOf env args
          else none
        geo.map fun g => ⟨g, ref⟩

def roundRectCmds (x0 y0 x1 y1 : Fx) (r : Array (Fx × Fx)) : Array PathCmd :=
  let k := fun (v : Fx) => Int.ediv (v * kappa16) 65536
  let (ax, ay) := r.getD 0 (0, 0)
  let (bx, by_) := r.getD 1 (0, 0)
  let (cx, cy) := r.getD 2 (0, 0)
  let (dx, dy) := r.getD 3 (0, 0)
  #[.moveTo ⟨x0 + ax, y0⟩,
    .lineTo ⟨x1 - bx, y0⟩,
    .cubicTo ⟨x1 - bx + k bx, y0⟩ ⟨x1, y0 + by_ - k by_⟩ ⟨x1, y0 + by_⟩,
    .lineTo ⟨x1, y1 - cy⟩,
    .cubicTo ⟨x1, y1 - cy + k cy⟩ ⟨x1 - cx + k cx, y1⟩ ⟨x1 - cx, y1⟩,
    .lineTo ⟨x0 + dx, y1⟩,
    .cubicTo ⟨x0 + dx - k dx, y1⟩ ⟨x0, y1 - dy + k dy⟩ ⟨x0, y1 - dy⟩,
    .lineTo ⟨x0, y0 + ay⟩,
    .cubicTo ⟨x0, y0 + ay - k ay⟩ ⟨x0 + ax - k ax, y0⟩ ⟨x0 + ax, y0⟩,
    .close]

def metricsOf (f : Font) : Metrics :=
  let z := Font.advance f (Font.glyphId f 0x30)
  let w := Font.advance f (Font.glyphId f 0x6C34)
  let g0 := Font.glyphId f 0x30
  let gw := Font.glyphId f 0x6C34
  { upem := f.unitsPerEm,
    zero := if g0 == 0 || z == 0 then f.unitsPerEm / 2 else z,
    ideo := if gw == 0 || w == 0 then f.unitsPerEm else w,
    cap := if f.capHeight > 0 then f.capHeight else f.ascent,
    xHeight := f.xHeight, ascent := f.ascent, descent := -f.descent, lineGap := f.lineGap }

def lineHeight (m : Metrics) (fs : Fx) : Fx :=
  let r := fun (n : Int) => Fx.round (scaleUnits m n fs) * 256
  r m.ascent + r m.descent + r m.lineGap

def fontLen (m : Metrics) (v fs : Fx) (unit : String) : Fx :=
  let n : Int :=
    if unit == "ch" then m.zero
    else if unit == "ic" then m.ideo
    else if unit == "cap" then m.cap
    else m.xHeight
  if unit == "lh" then Fx.clamp (Int.ediv (v * lineHeight m fs) 256)
  else if m.upem == 0 then 0
  else Fx.clamp (Int.ediv (v * n * fs) (256 * m.upem))

def load (href : ByteArray) (budget : Nat) : Option ByteArray × Nat :=
  match Image.dataUri href with
  | none => (none, 0)
  | some (mime, d) =>
    if !(mime == "image/svg+xml" || (mime == "text/plain" && !isRaster d)) then (none, 0)
    else if at' d 0 == 0x1f && at' d 1 == 0x8b then
      match Gzip.gunzip d budget with
      | none => (none, budget)
      | some s => (if s.validateUTF8 then some s else none, s.size)
    else if d.size ≤ budget && d.validateUTF8 then (some d, d.size)
    else (none, 0)

def layerBox (b : Int × Int × Int × Int) (cx0 cy0 cx1 cy1 : Nat) :
    Option (Nat × Nat × Nat × Nat) :=
  let (bx0, by0, bx1, by1) := b
  let x0 := max bx0 (cx0 : Int)
  let y0 := max by0 (cy0 : Int)
  let x1 := min bx1 (cx1 : Int)
  let y1 := min by1 (cy1 : Int)
  if x1 ≤ x0 || y1 ≤ y0 then none else some (x0.toNat, y0.toNat, x1.toNat, y1.toNat)

def splitQName (s : String) : String × String :=
  if s.contains ':' then
    let bs := s.toUTF8
    let i := findByte bs 0 58
    (toStr (bs.extract 0 i), toStr (bs.extract (i + 1) bs.size))
  else ("", s)

@[inline] def hexDigit (c : UInt8) : Option Nat :=
  if 48 ≤ c && c ≤ 57 then some (c.toNat - 48)
  else if 97 ≤ c && c ≤ 102 then some (c.toNat - 87)
  else if 65 ≤ c && c ≤ 70 then some (c.toNat - 55)
  else none

def mimeOf (hdr : ByteArray) : String :=
  let upto := hdr.extract 0 (findByte hdr 0 59)
  let t := trimBy upto isAsciiWs
  let k := findByte t 0 47
  if k ≥ t.size then "text/plain"
  else
    let ty := t.extract 0 k
    let sub := t.extract (k + 1) t.size
    if ty.size == 0 || sub.size == 0 || !(ty.toList.all isToken) || !(sub.toList.all isToken)
    then "text/plain"
    else toStr (lower t)

@[inline] def mul16 (a b : Int) : Int :=
  let m : Int := Int.ofNat ((a.natAbs * b.natAbs) >>> 16)
  if (a < 0) == (b < 0) then m else -m

def norm (neg : Bool) (m p : Nat) (sticky : Bool) : F32 :=
  if m == 0 then 0
  else
    let k := bitLen m
    if k ≤ 24 then
      let sh := 24 - k
      let t := p + bias
      if t ≤ pbias + sh then 0 else mk neg (m * p2 sh) (t - pbias - sh)
    else
      let drop := k - 24
      let q := m >>> drop
      let low := m &&& (p2 drop - 1)
      let half := p2 (drop - 1)
      let up := low > half || (low == half && (sticky || q &&& 1 == 1))
      let q := if up then q + 1 else q



      let carry := q == 16777216
      let q := if carry then 8388608 else q
      let t := p + drop + bias + (if carry then 1 else 0)
      if t ≤ pbias then 0 else mk neg q (t - pbias)

def blendSep (mode : BlendMode) (s d sa da : F32) : F32 :=
  let inv := fun v => sub one v
  let two := fun v => add v v
  match mode with
  | .multiply => add (add (mul s (inv da)) (mul d (inv sa))) (mul s d)
  | .screen => sub (add s d) (mul s d)
  | .darken => sub (add s d) (fmax (mul s da) (mul d sa))
  | .lighten => sub (add s d) (fmin (mul s da) (mul d sa))
  | .difference => sub (add s d) (two (fmin (mul s da) (mul d sa)))
  | .exclusion => sub (add s d) (two (mul s d))
  | .colorBurn =>
    if d == da then add d (mul s (inv da))
    else if s == 0 then mul d (inv sa)
    else
      let t := mul (mul (sub da d) sa) (div one s)
      add (add (mul sa (sub da (fmin da t))) (mul s (inv da))) (mul d (inv sa))
  | .colorDodge =>
    if d == 0 then mul s (inv da)
    else if s == sa then add s (mul d (inv sa))
    else
      let t := mul (mul d sa) (div one (sub sa s))
      add (add (mul sa (fmin da t)) (mul s (inv da))) (mul d (inv sa))
  | .hardLight =>
    let br := if le (two s) sa then two (mul s d)
      else sub (mul sa da) (two (mul (sub da d) (sub sa s)))
    add (add (mul s (inv da)) (mul d (inv sa))) br
  | .overlay =>
    let br := if le (two d) da then two (mul s d)
      else sub (mul sa da) (two (mul (sub da d) (sub sa s)))
    add (add (mul s (inv da)) (mul d (inv sa))) br
  | .softLight =>
    let m := if gt da 0 then div d da else 0
    let s2 := two s
    let m4 := two (two m)
    let darkSrc := mul d (add sa (mul (sub s2 sa) (sub one m)))
    let darkDst := add (mul (add (mul m4 m4) m4) (sub m one)) (mul seven m)
    let liteDst := sub (sqrt m) m
    let liteSrc := add (mul d sa) (mul (mul da (sub s2 sa)) (if le (two (two d)) da then darkDst else liteDst))
    add (add (mul s (inv da)) (mul d (inv sa))) (if le s2 sa then darkSrc else liteSrc)
  | _ => s

