  let mn := fmin r (fmin g b)
  let mx := fmax r (fmax g b)
  let l := lum r g b
  let clip := fun c =>
    let c := if ge mx 0 then c else add l (div (mul (sub c l) l) (sub l mn))
    let c := if gt mx a then add l (div (mul (sub c l) (sub a l)) (sub mx l)) else c
