  if hs == 1 && vs == 1 then byteAt pl (y * sw + x)
  else if hs > 2 || vs > 2 then byteAt pl ((y / vs) * sw + x / hs)
  else


    let r := y / vs
    let rb := if vs == 1 then r else if y % 2 == 0 then r - 1 else min (r + 1) (sh - 1)
    if hs == 1 then vTri pl sw r rb x else hTri pl sw r rb x

