  let pieces := rowBytes / 65535 + 2
  let out := storedRows rgba rowBytes rawSize pieces h 0 ((out.push 0x78).push 0x01) 0
  let out := if rawSize == 0 then blockHeader out 0 0 else out
  out ++ be32 (adler32Rows rgba rowBytes h)

