  let v : Int := if e ≥ 0 then num * (10 ^ e.toNat : Nat)
    else Int.ediv (2 * num + (10 ^ (-e).toNat : Nat)) (2 * (10 ^ (-e).toNat : Nat))
  let lim := Fx.maxVal * 256
  let v := if v > lim then lim else if v < -lim then -lim else v
  if neg then -v else v

