  let sy := fFix ts.d 65536
  let px := F32.add (F32.add (F32.mul x sx) (F32.mul y kx)) (fFix ts.e 256)
  let py := F32.add (F32.add (F32.mul x ky) (F32.mul y sy)) (fFix ts.f 256)
