def St.tick (st : St) : Except String St :=
  if st.work ≥ maxWork then throw "use: expansion exceeds the work budget"
  else pure { st with work := st.work + 1 }

def St.emit (st : St) (e : Xml.Event) : Except String St :=
  match e with
  | .open_ name attrs =>
    if st.elems ≥ maxElements then throw "use: expansion exceeds the element budget"
    else
      let k := if name == "clipPath" && (attr attrs "id").isSome then 1 else 0
      pure { st with out := st.out.push e, elems := st.elems + 1, clipPaths := st.clipPaths + k }
  | _ => pure { st with out := st.out.push e }

def isRecursive (c : Ctx) (j t : Nat) (origin : Option Nat) (st : St) :
    Except String (Bool × St) := do
  if t == j || origin == some t then return (true, st)
  let mut st := st
  for k in [t + 1 : c.endOf.getD t 0] do
    st ← st.tick
    match c.events.getD k default, c.target.getD k none with
    | .open_ "use" _, some t2 => if t2 == j || t2 == t then return (true, st)
    | _, _ => pure ()
  return (false, st)

def symbolGroupAttrs (attrs : Array Xml.Attr) (vbMat : Option Mat) : Array Xml.Attr :=
  let drop := ["transform", "transform-origin", "x", "y", "width", "height", "viewBox",
               "preserveAspectRatio", "refX", "refY"]
  let kept := attrs.filter (fun a => !drop.contains a.name)
  match vbMat with
  | some m => kept.push (mkAttr "transform" (fmtMat m))
  | none => kept

def fontSize (v : ByteArray) (parent : Int) (svgAttr : Bool) : Option Int :=
  let t := lower (trim v)
  let kw := [("xx-small", 9), ("x-small", 10), ("small", 13), ("medium", 16),
             ("large", 18), ("x-large", 24), ("xx-large", 32)]
  match kw.find? (fun (k, _) => eqAscii t k) with
  | some (_, px) => some (px * 256)
  | none =>
    (parseNum t).bind fun (n, u) =>
      if u == "px" || (u == "" && (svgAttr || n == 0)) then some n
      else if u == "pt" then some (n * 4 / 3)
      else if u == "em" then some (n * parent / 256)
      else if u == "rem" then some (n * 16)
      else if u == "%" then some (n * parent / 25600)
      else none

def fontWeight (v : ByteArray) (parent : Nat) : Option Nat :=
  let t := lower (trim v)
  if eqAscii t "normal" then some 400
  else if eqAscii t "bold" then some 700
  else if eqAscii t "bolder" then some (if parent < 350 then 400 else if parent < 550 then 700 else 900)
  else if eqAscii t "lighter" then some (if parent < 550 then 100 else if parent < 750 then 400 else 700)
  else match parseNum t with
    | some (n, "") => if n > 0 && n ≤ 1000 * 256 then some (n.toNat / 256) else none
    | _ => none

def faceOf (st : HStyle) : Except String Font :=
  let k := Text.baseFont 0 (Text.pickFace st.weight st.italic)
  match (FontSet.entries[k]?).bind (fun e => e.font ()) with
  | some f => if f.unitsPerEm == 0 then throw "foreignObject: embedded font has no units per em"
              else pure f
  | none => throw "foreignObject: embedded font missing"

def roundDiv (a b : Int) : Int :=
  if b == 0 then 0
  else if a ≥ 0 then Int.ediv (2 * a + b) (2 * b)
  else -(Int.ediv (2 * (-a) + b) (2 * b))

def conv (oBB : Bool) (l : Grad.LenPct) (ref : Int) : Int :=



  if !l.2 then (if oBB then l.1 else roundDiv l.1 65536)
  else if oBB then roundDiv l.1 100
  else roundDiv (l.1 * ref) (coordScale * 100)

def absRect (r : Resolved) (box : Option (Int × Int × Int × Int)) :
    Option (Int × Int × Int × Int) :=
  if !r.oBB then some (r.x, r.y, r.w, r.h)
  else match box with
    | none => none
    | some (bx0, by0, bw, bh) =>
      if bw ≤ 0 || bh ≤ 0 then none






      else some (bx0 + roundDiv (r.x * bw) coordScale, by0 + roundDiv (r.y * bh) coordScale,
                 roundDiv (r.w * bw) coordScale, roundDiv (r.h * bh) coordScale)

def viewBoxMat (vx vy vw vh : Int) (alignX alignY : Nat) (slice alignNone : Bool)
    (w h : Int) : Mat :=
  if vw ≤ 0 || vh ≤ 0 then Mat.identity
  else
    let sx := Grad.div16 w vw
    let sy := Grad.div16 h vh
    let (sx, sy) :=
      if alignNone then (sx, sy)
      else
        let s := if slice then (if sx < sy then sy else sx) else (if sx > sy then sy else sx)
        (s, s)
    let ox := -(Grad.mul16 vx sx)
    let oy := -(Grad.mul16 vy sy)
    let extraW := w - Grad.mul16 vw sx
    let extraH := h - Grad.mul16 vh sy
    let along := fun (align : Nat) (extra : Int) =>
      match align with | 0 => 0 | 2 => extra | _ => Int.ediv extra 2
    let tx := ox + along alignX extraW
    let ty := oy + along alignY extraH
    Mat.mk' sx 0 0 sy (Int.ediv tx 256) (Int.ediv ty 256)

def bicubicNear (t : F32) : F32 :=
  let m := fun a b c => F32.add (F32.mul a b) c
  m t (m t (m (F32.neg (F32.ofRat 21 18)) t (F32.ofRat 27 18)) (F32.ofRat 9 18)) (F32.ofRat 1 18)

def sampleAt (sh : Rt) (x16 y16 : Int) : Nat × Nat × Nat × Nat :=
  if sh.bicubic then sampleBicubic sh x16 y16
  else unpack (texelAt sh (Int.ediv x16 65536) (Int.ediv y16 65536))

def opacityQ (o : Nat) : Nat :=
  if o ≥ Svg.opacityOne then Canvas.opGrid
  else (o * Canvas.opGrid * 2 / Svg.opacityOne + 1) / 2

def hairCoverage (ctm : Mat) (w : Fx) : Option Int :=
  let fastLen := fun (x y : Int) =>
    let a := Fx.abs x
    let b := Fx.abs y
    if a < b then b + Int.ediv a 2 else a + Int.ediv b 2
  let len0 := fastLen (Int.ediv (ctm.a * w) 256) (Int.ediv (ctm.b * w) 256)
  let len1 := fastLen (Int.ediv (ctm.c * w) 256) (Int.ediv (ctm.d * w) 256)
  if len0 ≤ 65536 && len1 ≤ 65536 then some (Int.ediv (len0 + len1) 2) else none

def Job.mat (j : Job) (ts : Mat) : Mat :=
  let (sx, sy) := FilterApply.scaleOf ts
  Mat.mk' sx 0 0 sy (j.sx * 256) (j.sy * 256)

def setPre (fs : Array Filter.Resolved) (fi pi : Nat) (cv : Canvas) : Array Filter.Resolved :=
  fs.modify fi fun f => { f with prims := f.prims.modify pi fun p =>
    match p.kind with
    | .image s => { p with kind := .image { s with pre := some cv } }
    | _ => p }

def mapDemul (cv : Canvas) (f : Nat → Nat) : Canvas :=
  { cv with px := cv.px.map (fun p =>
    let a := chA p
    if a == 0 then p
    else
      let r := f (Canvas.unpremul (chR p) a)
      let g := f (Canvas.unpremul (chG p) a)
      let b := f (Canvas.unpremul (chB p) a)
      Canvas.pack (Canvas.premul r a) (Canvas.premul g a) (Canvas.premul b a) a) }

def convert (cv : Canvas) (toLin : Bool) : Canvas :=
  let tab := if toLin then srgbToLin else linToSrgb
  mapDemul cv (fun c => tab.getD c 0)

def hue3 (deg : F32) : Array F32 :=

  let rad := F32.mul deg (F32.div (ofRatBig piNum piDen) (F32.ofNat 180))
  let (a2, a1) := sinCosF32 rad
  let r := fun (n : Nat) => ofRatBig n 1000
  let t := fun (k0 k1 k2 : F32) => F32.add (F32.add k0 (F32.mul k1 a1)) (F32.mul k2 a2)
  let n := F32.neg
  #[t (r 213) (r 787) (n (r 213)), t (r 715) (n (r 715)) (n (r 715)), t (r 72) (n (r 72)) (r 928),
    t (r 213) (n (r 213)) (r 143), t (r 715) (r 285) (r 140), t (r 72) (n (r 72)) (n (r 283)),
    t (r 213) (n (r 213)) (n (r 787)), t (r 715) (n (r 715)) (r 715), t (r 72) (r 928) (r 72)]

def colorMatrix (k : CMKind) (cv : Canvas) : Canvas :=
  let dem := fun (p : Nat) =>
    let a := chA p
    if a == 0 then (0, 0, 0, 0)
    else (Canvas.unpremul (chR p) a, Canvas.unpremul (chG p) a, Canvas.unpremul (chB p) a, a)
  let out := fun (r g b a : Nat) =>
    Canvas.pack (Canvas.premul r a) (Canvas.premul g a) (Canvas.premul b a) a
  match k with
  | .matrix m =>
    let T := (List.range 20).toArray.map fun i => mulTab (m.getD i 0)
    let row := fun (j r g b a : Nat) =>
      f32TruncU8 (F32.add (F32.add (F32.add (F32.add ((T.getD (5 * j) #[]).getD r 0)
        ((T.getD (5 * j + 1) #[]).getD g 0)) ((T.getD (5 * j + 2) #[]).getD b 0))
        ((T.getD (5 * j + 3) #[]).getD a 0)) (m.getD (5 * j + 4) 0))
    { cv with px := cv.px.map (fun p =>
      let (r, g, b, a) := dem p
      out (row 0 r g b a) (row 1 r g b a) (row 2 r g b a) (row 3 r g b a)) }
  | .saturate _ | .hueRotate _ =>
    let m := match k with
      | .saturate v => sat3 (if F32.isNeg v then 0 else v)
      | .hueRotate d => hue3 d
      | _ => #[]
    let T := (List.range 9).toArray.map fun i => mulTab (m.getD i 0)
    let row := fun (j r g b : Nat) =>
      f32TruncU8 (F32.add (F32.add ((T.getD (3 * j) #[]).getD r 0)
        ((T.getD (3 * j + 1) #[]).getD g 0)) ((T.getD (3 * j + 2) #[]).getD b 0))
    { cv with px := cv.px.map (fun p =>
      let (r, g, b, a) := dem p
      out (row 0 r g b) (row 1 r g b) (row 2 r g b) a) }
  | .lumToAlpha =>
    let tr := mulTab (ofRatBig 2125 10000)
    let tg := mulTab (ofRatBig 7154 10000)
    let tb := mulTab (ofRatBig 721 10000)
    { cv with px := cv.px.map (fun p =>
      let (r, g, b, _) := dem p
      f32TruncU8 (F32.add (F32.add (tr.getD r 0) (tg.getD g 0)) (tb.getD b 0))) }

def iirCoeffs (s16 : Nat) : Nat × Nat :=
  let S : Nat := 4294967296
  let L := s16 * s16 / 8
  if L == 0 then (0, S)
  else
    let sq := Nat.sqrt ((S + 4 * L) * S)
    let dnu := (S + 2 * L - sq) * S / (2 * L)
    let R := dnu * S / L
    (dnu, R * R / S * R / S * R / S)

def devRect (ts : Mat) (r : URect) : Option (Int × Int × Int × Int) :=
  let ps := #[ts.apply ⟨r.x, r.y⟩, ts.apply ⟨r.x + r.w, r.y⟩, ts.apply ⟨r.x, r.y + r.h⟩,
              ts.apply ⟨r.x + r.w, r.y + r.h⟩]
  let x0 := ps.foldl (fun m p => min m p.x) (ps.getD 0 ⟨0, 0⟩).x
  let y0 := ps.foldl (fun m p => min m p.y) (ps.getD 0 ⟨0, 0⟩).y
  let x1 := ps.foldl (fun m p => max m p.x) (ps.getD 0 ⟨0, 0⟩).x
  let y1 := ps.foldl (fun m p => max m p.y) (ps.getD 0 ⟨0, 0⟩).y
  if x1 ≤ x0 || y1 ≤ y0 then none
  else some (Fx.floor x0, Fx.floor y0, max 1 (Fx.ceil (x1 - x0)), max 1 (Fx.ceil (y1 - y0)))

def roundAwayDiv (n : Int) (d : Nat) : Int :=
  if n ≥ 0 then Int.ediv (2 * n + (d : Int)) (2 * (d : Int))
  else -(Int.ediv (2 * (-n) + (d : Int)) (2 * (d : Int)))

def powGeneral (base exp : F32) : F32 :=
  let lnC := lnBig base
  let (negE, numE, denE) := f32Rat exp
  let eScaledN : Nat := numE * lnScale / denE
  let eScaled : Int := if negE then -(eScaledN : Int) else (eScaledN : Int)
  let y : Int := Int.ediv (eScaled * lnC) (lnScale : Int)
  let n : Int := if y ≥ 0 then Int.ediv (2 * y + ln2Scaled) (2 * ln2Scaled)
                 else -(Int.ediv (2 * (-y) + ln2Scaled) (2 * ln2Scaled))
  let r : Int := y - n * ln2Scaled
  if n > 300 then ofRatBig (10 ^ 40) 1
  else if n < -300 then 0
  else
    let E := expSmall r
    if n ≥ 0 then ofRatBig (E * 2 ^ n.toNat) lnScale
    else ofRatBig E (lnScale * 2 ^ (-n).toNat)

def demultiply (cv : Canvas) : Canvas :=
  { cv with px := cv.px.map (fun p =>
      let a := cA p
      if a == 0 then p
      else Canvas.pack (Canvas.unpremul (cR p) a) (Canvas.unpremul (cG p) a)
        (Canvas.unpremul (cB p) a) a) }

def dirUnit16 (x y : Int) : Int × Int :=
  if x == 0 && y == 0 then (65536, 0)
  else
    let len : Nat := Nat.sqrt (x.natAbs * x.natAbs + y.natAbs * y.natAbs)
    if len == 0 then (65536, 0) else (Int.ediv (x * 65536) len, Int.ediv (y * 65536) len)

def elevateQuad (p0 c p : Pt) : Pt × Pt :=
  (⟨Int.ediv (p0.x + 2 * c.x) 3, Int.ediv (p0.y + 2 * c.y) 3⟩,
   ⟨Int.ediv (p.x + 2 * c.x) 3, Int.ediv (p.y + 2 * c.y) 3⟩)

def noAlpha : Paint → Paint
  | .solid c => .solid { c with a := 255 }
  | p => p

def expand (doc : Doc) : Doc :=
  if doc.markers.isEmpty then doc else
  let idMap := buildIdMap doc.markers
  let (nodes, uses, ctxUses, _) :=
    expandContentList doc idMap maxMarkerDepth #[] Mat.identity default doc.nodes doc.uses
      doc.ctxUses maxMarkerNodes
  { doc with nodes := nodes, uses := uses, ctxUses := ctxUses }

def newAcc (W H : Nat) (b : Option Box) : Mask :=
  match b with
  | none => ⟨0, 0, 0, 0, #[]⟩
  | some b =>
    let x0 := Int.toNat (Fx.floor b.x0 - 1)
    let y0 := Int.toNat (Fx.floor b.y0 - 1)
    let x1 := Nat.min W (Int.toNat (Fx.ceil b.x1 + 1))
    let y1 := Nat.min H (Int.toNat (Fx.ceil b.y1 + 1))
    if x1 ≤ x0 || y1 ≤ y0 then ⟨0, 0, 0, 0, #[]⟩
    else ⟨x0, y0, x1 - x0, y1 - y0, Array.replicate ((x1 - x0) * (y1 - y0)) 255⟩

def childMat (T : Mat) (ch : Svg.ClipChild) : Mat :=
  let m := T.mul ch.ctm
  if ch.fine then m.mul fineScale else m
